import{_ as e,c as s,o as a,ag as i}from"./chunks/framework.DCv_I274.js";const k=JSON.parse('{"title":"How the web works","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/how-the-web-works.md","filePath":"fundamentals/how-the-web-works.md","lastUpdated":null}'),o={name:"fundamentals/how-the-web-works.md"};function n(d,t,r,h,l,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="how-the-web-works" tabindex="-1">How the web works <a class="header-anchor" href="#how-the-web-works" aria-label="Permalink to &quot;How the web works&quot;">​</a></h1><p>Everything in these docs sits on one idea: <strong>a client sends a request, a server sends back a response.</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> Browser / mobile app / Postman                 Your Laravel app</span></span>
<span class="line"><span> ─────────────────────────────                  ─────────────────</span></span>
<span class="line"><span>          CLIENT          ── HTTP request ──►       SERVER</span></span>
<span class="line"><span>                          ◄─ HTTP response ──</span></span></code></pre></div><h2 id="the-pieces" tabindex="-1">The pieces <a class="header-anchor" href="#the-pieces" aria-label="Permalink to &quot;The pieces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>What it is</th><th>Example</th></tr></thead><tbody><tr><td><strong>Client</strong></td><td>The program that asks</td><td>Chrome, a Vue app, a phone app, <code>curl</code></td></tr><tr><td><strong>Server</strong></td><td>The program that answers</td><td>PHP + Laravel behind Apache/Nginx</td></tr><tr><td><strong>URL</strong></td><td>The address of a resource</td><td><code>https://api.school.edu/api/v1/campuses?page=2</code></td></tr><tr><td><strong>DNS</strong></td><td>The phonebook that turns a name into an IP address</td><td><code>api.school.edu</code> → <code>203.0.113.10</code></td></tr><tr><td><strong>HTTP</strong></td><td>The language client and server speak</td><td><code>GET /api/v1/campuses HTTP/1.1</code></td></tr><tr><td><strong>HTTPS</strong></td><td>HTTP inside an encrypted TLS tunnel</td><td>the padlock in the address bar</td></tr></tbody></table><h3 id="anatomy-of-a-url" tabindex="-1">Anatomy of a URL <a class="header-anchor" href="#anatomy-of-a-url" aria-label="Permalink to &quot;Anatomy of a URL&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.school.edu:443/api/v1/campuses?page=2&amp;search=main#top</span></span>
<span class="line"><span>└─┬─┘   └─────┬──────┘ └┬┘ └──────┬───────┘ └────────┬───────┘ └┬┘</span></span>
<span class="line"><span>scheme       host      port      path            query string   fragment</span></span></code></pre></div><ul><li>The <strong>path</strong> tells the server <em>what</em> you want.</li><li>The <strong>query string</strong> adds options (<code>page</code>, <code>search</code>). Laravel reads it with <code>$request-&gt;input(&#39;page&#39;)</code>.</li><li>The <strong>fragment</strong> (<code>#top</code>) never reaches the server. Only the browser uses it.</li></ul><h2 id="an-http-request" tabindex="-1">An HTTP request <a class="header-anchor" href="#an-http-request" aria-label="Permalink to &quot;An HTTP request&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/campuses </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api.school.edu</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer eyJhbGciOi...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Accept</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MAIN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Main Campus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol><li><strong>Request line:</strong> method, path, protocol version.</li><li><strong>Headers:</strong> metadata as <code>Name: value</code> lines.</li><li><strong>Blank line.</strong></li><li><strong>Body</strong> (optional): the data, here JSON.</li></ol><h3 id="methods-verbs" tabindex="-1">Methods (verbs) <a class="header-anchor" href="#methods-verbs" aria-label="Permalink to &quot;Methods (verbs)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Meaning</th><th>Has a body?</th><th>Safe to repeat?</th></tr></thead><tbody><tr><td><code>GET</code></td><td>Read</td><td>no</td><td>yes</td></tr><tr><td><code>POST</code></td><td>Create / do an action</td><td>yes</td><td>no</td></tr><tr><td><code>PUT</code></td><td>Replace completely</td><td>yes</td><td>yes</td></tr><tr><td><code>PATCH</code></td><td>Change some fields</td><td>yes</td><td>usually</td></tr><tr><td><code>DELETE</code></td><td>Remove</td><td>rarely</td><td>yes</td></tr></tbody></table><p>&quot;Safe to repeat&quot; (<strong>idempotent</strong>) means sending it twice has the same effect as once. It matters when a network error makes the client retry.</p><h2 id="an-http-response" tabindex="-1">An HTTP response <a class="header-anchor" href="#an-http-response" aria-label="Permalink to &quot;An HTTP response&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 201</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Created</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-store</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Campus &#39;Main Campus&#39; created successfully!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="status-codes" tabindex="-1">Status codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to &quot;Status codes&quot;">​</a></h3><p>The first digit is the family:</p><table tabindex="0"><thead><tr><th>Family</th><th>Meaning</th><th>Codes you will use</th></tr></thead><tbody><tr><td><code>2xx</code></td><td>It worked</td><td><code>200 OK</code>, <code>201 Created</code>, <code>204 No Content</code></td></tr><tr><td><code>3xx</code></td><td>Go somewhere else</td><td><code>301</code>, <code>302</code> redirects (Blade apps)</td></tr><tr><td><code>4xx</code></td><td><strong>The client</strong> made a mistake</td><td><code>400</code> bad request, <code>401</code> not logged in, <code>403</code> not allowed, <code>404</code> not found, <code>409</code> conflict, <code>419</code> expired CSRF token (Blade), <code>422</code> invalid input, <code>429</code> too many requests</td></tr><tr><td><code>5xx</code></td><td><strong>The server</strong> failed</td><td><code>500</code> bug, <code>503</code> down for maintenance</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">401 vs 403</p><p><strong>401 Unauthorized</strong> means &quot;I don&#39;t know who you are&quot;: log in. <strong>403 Forbidden</strong> means &quot;I know who you are, and you may not do this&quot;.</p></div><h3 id="headers-you-will-meet" tabindex="-1">Headers you will meet <a class="header-anchor" href="#headers-you-will-meet" aria-label="Permalink to &quot;Headers you will meet&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Header</th><th>Direction</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>both</td><td>Format of the body (<code>application/json</code>, <code>text/html</code>)</td></tr><tr><td><code>Accept</code></td><td>request</td><td>Format the client wants back. Send <code>application/json</code> to Laravel APIs so errors come back as JSON</td></tr><tr><td><code>Authorization</code></td><td>request</td><td>Credentials, e.g. <code>Bearer &lt;token&gt;</code></td></tr><tr><td><code>Cookie</code> / <code>Set-Cookie</code></td><td>request / response</td><td>Small values the browser stores and sends back automatically</td></tr><tr><td><code>Origin</code></td><td>request</td><td>Which website made a browser request (used by CORS and CSRF checks)</td></tr><tr><td><code>Cache-Control</code></td><td>response</td><td>Whether the response may be cached</td></tr><tr><td><code>Location</code></td><td>response</td><td>Where a redirect or a newly created resource is</td></tr></tbody></table><h2 id="http-is-stateless" tabindex="-1">HTTP is stateless <a class="header-anchor" href="#http-is-stateless" aria-label="Permalink to &quot;HTTP is stateless&quot;">​</a></h2><p>The server forgets you after every response. To &quot;stay logged in&quot; the client must prove who it is <strong>on every request</strong>. There are two common ways:</p><table tabindex="0"><thead><tr><th></th><th>Session cookie (classic web apps, Blade)</th><th>Token (APIs, SPAs, mobile)</th></tr></thead><tbody><tr><td>After login the server...</td><td>stores a session and sends a cookie with its id</td><td>signs a token and sends it in the body</td></tr><tr><td>The client then sends...</td><td>the cookie, automatically</td><td><code>Authorization: Bearer &lt;token&gt;</code>, explicitly</td></tr><tr><td>Server-side storage</td><td>session table / files</td><td>none for the access token</td></tr><tr><td>Used in these docs for</td><td>Blade pages</td><td>the API</td></tr></tbody></table><p>These docs use <strong>both ideas together</strong> for the API: a short-lived access token in memory plus a long-lived refresh token in an httpOnly cookie. See <a href="/foundations/08-jwt-access-tokens">JWT access tokens</a> and <a href="/foundations/09-refresh-sessions">Refresh sessions</a>.</p><h2 id="what-happens-when-you-open-a-page" tabindex="-1">What happens when you open a page <a class="header-anchor" href="#what-happens-when-you-open-a-page" aria-label="Permalink to &quot;What happens when you open a page&quot;">​</a></h2><ol><li>The browser asks <strong>DNS</strong> for the IP of the host.</li><li>It opens a <strong>TCP</strong> connection and a <strong>TLS</strong> (HTTPS) session.</li><li>It sends an <strong>HTTP request</strong>.</li><li>The web server (Nginx/Apache) hands PHP requests to <strong>PHP-FPM</strong>, which runs <code>public/index.php</code>: Laravel&#39;s single entry point.</li><li>Laravel <strong>routes</strong> the request, runs middleware, your controller, and returns a <strong>response</strong>.</li><li>For HTML, the browser then requests every CSS, JS and image file the page references, and renders it.</li></ol><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><p>Open your browser&#39;s <strong>DevTools → Network</strong> tab (F12) and reload any site. Click a request: you will see the method, URL, status, request headers, response headers and body, exactly as described above.</p><p>With <code>curl</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span></span></code></pre></div><p><code>-i</code> prints the status line and headers before the body.</p><p>Next: <a href="/fundamentals/web-programming-basics">Web programming basics</a></p>`,34)])])}const g=e(o,[["render",n]]);export{k as __pageData,g as default};
